-- HMT Collabs: regional, technician-group and automation foundation.
CREATE TABLE IF NOT EXISTS countries (code TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO countries(code,name,currency) VALUES ('MU','Mauritius','MUR'),('MG','Madagascar','MGA'),('RW','Rwanda','RWF'),('BI','Burundi','BIF');
CREATE TABLE IF NOT EXISTS support_groups (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS support_group_members (group_id TEXT NOT NULL REFERENCES support_groups(id), user_id TEXT NOT NULL REFERENCES users(id), group_role TEXT NOT NULL CHECK(group_role IN ('member','lead')), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS ticket_assignments (ticket_id TEXT PRIMARY KEY REFERENCES tickets(id), group_id TEXT NOT NULL REFERENCES support_groups(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflow_rules (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, event_name TEXT NOT NULL, conditions_json TEXT NOT NULL, actions_json TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS automation_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), rule_id TEXT REFERENCES workflow_rules(id), subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, outcome TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, country_code TEXT REFERENCES countries(code), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS opportunities (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'prospection', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS renewals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, expiry_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
